if($p==='dashboard') {
 $id=(int)($_GET['event_id']??0);$events=all('SELECT id,name FROM events ORDER BY starts_at DESC');$w=$id?' WHERE event_id=?':'';$a=$id?[$id]:[];
 $tot=one("SELECT COUNT(*) total,COALESCE(SUM(status='Pagado'),0) paid,COALESCE(SUM(status='En revisión'),0) reviewing,COALESCE(SUM(CASE WHEN status='Pagado' THEN monto_cobrado ELSE 0 END),0) income,COALESCE(SUM(CASE WHEN status<>'Anulado' THEN GREATEST(0,price-monto_cobrado) ELSE 0 END),0) pending FROM registrations".$w,$a);
 $materials=(float)q('SELECT COALESCE(SUM(stock*unit_cost),0) FROM materials'.$w,$a)->fetchColumn();$expenses=(float)q('SELECT COALESCE(SUM(amount),0) FROM expenses'.$w,$a)->fetchColumn();headerPage('Resumen y finanzas'); ?>
 <div class="card p-4 no-print"><form method="get"><input type="hidden" name="p" value="dashboard"><?php selectField('event_id','Evento',[0=>'Todos']+array_column($events,'name','id'),(string)$id);?><button class="btn btn-primary">Consultar</button> <button type="button" class="btn btn-outline-primary" onclick="print()">Imprimir</button></form></div><div class="row"><?php foreach(['Inscripciones'=>$tot['total'],'Pagos confirmados'=>$tot['paid'],'En revisión'=>$tot['reviewing'],'Ingresos confirmados'=>money($tot['income']),'Costos de materiales'=>money($materials),'Otros gastos'=>money($expenses),'Saldo del evento'=>money($tot['income']-$materials-$expenses),'Por cobrar'=>money($tot['pending'])] as $label=>$value):?><div class="col-md-3"><div class="small-box bg-<?=($label==='Saldo del evento'?'success':'primary')?>"><div class="inner"><h3><?=e($value)?></h3><p><?=e($label)?></p></div></div></div><?php endforeach?></div>
 <div class="row"><div class="col-lg-6"><div class="card p-4"><h3>Ingresos por forma de pago</h3><table class="table"><tr><th>Forma</th><th>Inscritos</th><th>Cobrado</th></tr><?php foreach(all("SELECT payment_method,COUNT(*) n,SUM(monto_cobrado) total FROM registrations WHERE status='Pagado'".($id?' AND event_id=?':'').' GROUP BY payment_method',$a) as $row)echo '<tr><td>'.e($row['payment_method']).'</td><td>'.e($row['n']).'</td><td>'.money($row['total']).'</td></tr>';?></table></div></div><div class="col-lg-6"><div class="card p-4"><h3>Resumen por evento</h3><div class="table-responsive"><table class="table"><tr><th>Evento</th><th>Cobrado</th><th>Gastos</th><th>Saldo</th></tr><?php foreach(all("SELECT e.id,e.name,(SELECT COALESCE(SUM(monto_cobrado),0) FROM registrations r WHERE r.event_id=e.id AND r.status='Pagado') income,(SELECT COALESCE(SUM(stock*unit_cost),0) FROM materials m WHERE m.event_id=e.id)+(SELECT COALESCE(SUM(amount),0) FROM expenses g WHERE g.event_id=e.id) costs FROM events e".($id?' WHERE e.id=?':''),$a) as $ev)echo '<tr><td>'.e($ev['name']).'</td><td>'.money($ev['income']).'</td><td>'.money($ev['costs']).'</td><td>'.money($ev['income']-$ev['costs']).'</td></tr>';?></table></div></div></div></div>
 <div class="card p-4"><h3>Otros gastos</h3><table class="table"><tr><th>Fecha</th><th>Evento</th><th>Categoría</th><th>Detalle</th><th>Monto</th></tr><?php foreach(all('SELECT g.*,e.name,COALESCE(c.name,\'Sin categoría\') category_name FROM expenses g JOIN events e ON e.id=g.event_id LEFT JOIN expense_categories c ON c.id=g.category_id'.($id?' WHERE g.event_id=?':'').' ORDER BY g.spent_on DESC',$a) as $g)echo '<tr><td>'.e($g['spent_on']).'</td><td>'.e($g['name']).'</td><td>'.e($g['category_name']).'</td><td>'.e($g['description']).'</td><td>'.money($g['amount']).'</td></tr>';?></table><form method="post" class="no-print"><?=csrf()?><input type="hidden" name="action" value="expense"><div class="row"><div class="col-md-4"><?php selectField('event_id','Evento',array_column($events,'name','id'),(string)$id);?></div><div class="col-md-4"><?php field('description','Detalle del gasto');?></div><div class="col-md-2"><?php field('amount','Monto (Bs)','','number');?></div><div class="col-md-2"><?php field('spent_on','Fecha',date('Y-m-d'),'date');?></div></div><?php selectField('category_id','Categoría de gasto',[0=>'Sin categoría']+array_column(all('SELECT id,name FROM expense_categories WHERE active=1 ORDER BY name'),'name','id'));?><a class="btn btn-outline-primary mb-3" href="<?=url('p=categories')?>">Crear / gestionar categorías</a> <a class="btn btn-outline-primary mb-3" href="<?=url('p=expense_report&event_id='.$id)?>">Reporte por categorías</a><br><button class="btn btn-primary">Registrar gasto</button></form></div><?php footerPage();exit;
